CREATE TABLE funding_sources (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  source_type TEXT NOT NULL DEFAULT 'other',
  grant_number TEXT,
  fiscal_year_start TEXT NOT NULL,
  fiscal_year_end TEXT NOT NULL,
  total_amount REAL NOT NULL DEFAULT 0,
  restrictions TEXT,
  notes TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  -- Opioid settlement funds (migration 38): the allowable use (constants.SETTLEMENT_USES — national
  -- settlement Exhibit E) and the California High Impact Abatement Activity (constants.SETTLEMENT_HIAA, or
  -- 'none') that spending from this fund counts toward, unless an expenditure says otherwise.
  settlement_use TEXT,
  settlement_hiaa TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
INSERT INTO "funding_sources"("id","name","source_type","grant_number","fiscal_year_start","fiscal_year_end","total_amount","restrictions","notes","is_active","settlement_use","settlement_hiaa","created_at","updated_at") VALUES('0b4ae00f-c653-4b08-958c-44455ed6b383','Opioid Settlement – Navigation FY27','opioid_settlement','OS-2026-014','2026-07-01','2027-06-30',180000,'Abatement uses only; no indirect above 10%',NULL,1,NULL,NULL,'2026-09-26T23:20:34.472Z','2026-09-26T23:20:34.472Z');
INSERT INTO "funding_sources"("id","name","source_type","grant_number","fiscal_year_start","fiscal_year_end","total_amount","restrictions","notes","is_active","settlement_use","settlement_hiaa","created_at","updated_at") VALUES('8064ba0a-85ab-4842-bc85-abf839043f03','SOR IV – Peer Support','sor_grant','SOR-4-0087','2026-01-01','2026-12-31',60000,'Peer support and recovery housing only',NULL,1,NULL,NULL,'2026-09-26T23:20:34.473Z','2026-09-26T23:20:34.473Z');
CREATE TABLE budget_lines (
  id TEXT PRIMARY KEY,
  funding_source_id TEXT NOT NULL REFERENCES funding_sources(id) ON DELETE CASCADE,
  -- A budget line can sit inside a larger one (a grant broken into program-level allocations broken into
  -- line items) instead of every line being a flat peer under the fund. Always within the same fund; the
  -- application enforces that plus cycle-safety, since SQLite has no way to express either as a constraint.
  parent_id TEXT REFERENCES budget_lines(id) ON DELETE CASCADE,
  category TEXT NOT NULL,
  label TEXT,
  allocated_amount REAL NOT NULL DEFAULT 0,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
