CREATE TABLE resources (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'other',
  organization TEXT,
  phone TEXT,
  fax TEXT,
  email TEXT,
  website TEXT,
  address TEXT,
  city TEXT,
  zip TEXT,
  hours TEXT,
  eligibility TEXT,
  services TEXT,
  languages TEXT,
  accepts_medicaid INTEGER DEFAULT 0,
  accepts_uninsured INTEGER DEFAULT 0,
  mat_offered TEXT,
  capacity_notes TEXT,
  contact_person TEXT,
  summary TEXT,                         -- plain-language overview shown on the profile
  service_tags TEXT,                    -- comma separated SERVICE_TAGS
  levels_of_care TEXT,                  -- comma separated ASAM levels
  populations TEXT,                     -- who they serve (comma separated POPULATIONS)
  intake_process TEXT,
  cost_notes TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  last_verified_at TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('7fd7862b-55b6-436e-abc4-4c435f282ce6','County OTP','mat_otp',NULL,'555-0199',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,'2026-09-26T23:20:33.785Z','2026-09-26T23:20:33.785Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('083df102-453f-425e-933e-2168cc2514c7','Riverside Recovery Center','residential',NULL,'555-0200',NULL,NULL,'https://example.org/riverside-recovery-center','200 Sample Ave','Springfield','00000','Mon–Fri 8–5; intake line 24/7',NULL,'28-day residential; medically supervised. Adults 18+.','English, Spanish',1,1,'buprenorphine, naltrexone',NULL,NULL,'A 42-bed residential program on the river with medical staff on site around the clock. Clients start with a medical assessment and, if needed, medically supervised withdrawal, then move into a structured 28-day program of group and individual counseling, MAT (buprenorphine or naltrexone), family sessions and discharge planning. Most clients step down to Northside IOP or Bridge Housing.','residential,detox,mat_buprenorphine,mat_naltrexone,individual_counseling,group_counseling,family_program,co_occurring,aftercare,spanish_speaking','3.5, 3.7','adults,women,men,justice_involved','Call the intake line any time; a nurse screens by phone in about 20 minutes. Bring ID and insurance card if you have them; neither is required to be admitted. Beds are usually available within 1–3 days.','Medicaid and most commercial plans; county-funded beds for uninsured residents.',1,'2026-09-25','Sample resource (fictional)','2026-09-26T23:20:34.240Z','2026-09-26T23:20:34.240Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('613a21d3-1e74-4aee-ae77-a5bf5d90b635','County Opioid Treatment Program','mat_otp',NULL,'555-0201',NULL,NULL,'https://example.org/county-opioid-treatment-program','240 Sample Ave','Springfield','00000','Dosing 5:30am–11am daily',NULL,'Methadone and buprenorphine; same-day intake Tue/Thu.','English, Spanish',1,1,'methadone, buprenorphine',NULL,NULL,'The county''s licensed opioid treatment program. Daily observed methadone or buprenorphine dosing with take-home doses earned over time, plus counseling, peer support and on-site naloxone. Same-day intake on Tuesdays and Thursdays for anyone who arrives before 9am.','mat_methadone,mat_buprenorphine,medication_management,individual_counseling,group_counseling,peer_support,naloxone,same_day_intake,walk_in,spanish_speaking','OTP','adults,pregnant_parenting,justice_involved','Walk in Tue/Thu before 9am with a photo ID if possible. A navigator warm handoff speeds things up: call the intake nurse the day before.','Medicaid covers dosing in full; sliding scale for uninsured (about $15/week).',1,'2026-07-01','Sample resource (fictional)','2026-09-26T23:20:34.331Z','2026-09-26T23:20:34.331Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('d9e15a66-ec5e-4321-917b-7ebe49d0c1bd','Hope Street Detox','detox_withdrawal_mgmt',NULL,'555-0202',NULL,NULL,'https://example.org/hope-street-detox','280 Sample Ave','Springfield','00000','24/7',NULL,'Social and medical detox; call for bed availability.','English',1,1,NULL,NULL,NULL,'Short-stay (3–7 day) withdrawal management with nursing 24/7 and a physician on call. Comfort medications for opioid, alcohol and benzodiazepine withdrawal. Staff connect every client to a next step before discharge.','detox,medical_care,naloxone,crisis_24_7,aftercare','3.2, 3.7','adults','Call for bed availability; if a bed is open the client can come the same day. Ambulance or navigator transport is fine.','No cost to county residents.',1,'2026-08-11','Sample resource (fictional)','2026-09-26T23:20:34.366Z','2026-09-26T23:20:34.366Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('ed1d4165-878e-4319-bd77-c5ed0167c22d','Bridge Housing Collaborative','sober_living',NULL,'555-0203',NULL,NULL,'https://example.org/bridge-housing-collaborative','320 Sample Ave','Springfield','00000','Mon–Fri 9–4',NULL,'Recovery housing; 30 days sober required.','English',1,0,NULL,NULL,NULL,'Shared recovery homes (2–3 people per room) with house managers, weekly house meetings and required recovery-meeting attendance. Residents may stay up to 12 months while they work, study or attend treatment.','sober_living,housing,peer_support,employment,aftercare',NULL,'adults,men,women','Application plus a short interview; 30 days of sobriety and a referral from a treatment provider or navigator are required.','Rent $450/month; first month can be covered by the housing assistance line.',1,'2026-08-16','Sample resource (fictional)','2026-09-26T23:20:34.378Z','2026-09-26T23:20:34.378Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('38c102fb-421d-4b48-972a-d23a8be3b012','Downtown Shelter','shelter',NULL,'555-0204',NULL,NULL,'https://example.org/downtown-shelter','360 Sample Ave','Springfield','00000','Check-in 6pm',NULL,'Emergency shelter; low-barrier; pets allowed.','English, Spanish',0,1,NULL,NULL,NULL,'Low-barrier overnight shelter with 120 beds, showers, lockers and a hot dinner. Sobriety is not required. Case managers on site help with IDs, benefits and housing applications.','housing,case_management,walk_in,harm_reduction,naloxone',NULL,'adults,unhoused,veterans','Walk in at 6pm; no referral needed.','Free.',1,'2026-08-08','Sample resource (fictional)','2026-09-26T23:20:34.389Z','2026-09-26T23:20:34.389Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('3425e99e-b7f8-464b-b7a9-b1ca18274866','Community Harm Reduction Coalition','syringe_services',NULL,'555-0205',NULL,NULL,'https://example.org/community-harm-reduction-coalition','400 Sample Ave','Springfield','00000','Tue/Thu 1–5; mobile van Sat',NULL,'Syringe services, naloxone, fentanyl test strips, wound care.','English, Spanish',0,1,NULL,NULL,NULL,'Peer-run harm reduction center and mobile van. Free naloxone, fentanyl and xylazine test strips, safer-use supplies, wound care by a nurse, HIV/HCV testing and a warm, no-judgment place to sit down.','harm_reduction,naloxone,syringe_services,medical_care,peer_support,walk_in,spanish_speaking',NULL,'adults,unhoused,lgbtq','No referral or ID needed. The van schedule is posted on their website weekly.','Free.',1,'2026-09-03','Sample resource (fictional)','2026-09-26T23:20:34.395Z','2026-09-26T23:20:34.395Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('2487fd45-72c3-4e85-8cb5-dc42c192ceb5','Valley Behavioral Health','mental_health',NULL,'555-0206',NULL,NULL,'https://example.org/valley-behavioral-health','440 Sample Ave','Springfield','00000','Mon–Fri 8–6',NULL,'Outpatient mental health; co-occurring track.','English',1,0,NULL,NULL,NULL,'Community mental health center with psychiatry, therapy and a co-occurring disorders track for people managing both substance use and mental health conditions. Telehealth available.','mental_health,co_occurring,medication_management,individual_counseling,group_counseling,telehealth,trauma_informed','1.0','adults,adolescents,families','Phone intake, then an assessment within two weeks. Navigators can request an expedited slot for clients leaving detox or jail.','Medicaid and commercial insurance; county contract covers uninsured residents.',1,'2026-07-20','Sample resource (fictional)','2026-09-26T23:20:34.406Z','2026-09-26T23:20:34.406Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('36e23fa0-28c8-4754-848d-6230524517e8','Second Chance Legal Aid','legal',NULL,'555-0207',NULL,NULL,'https://example.org/second-chance-legal-aid','480 Sample Ave','Springfield','00000','Wed 10–2 walk-in',NULL,'Expungement, warrants, benefits appeals.','English',0,1,NULL,NULL,NULL,'Free civil legal help for people in recovery: expungement, clearing warrants, driver''s license reinstatement, benefits appeals and landlord issues.','legal_help,walk_in',NULL,'adults,justice_involved','Walk in Wednesdays or call for an appointment.','Free.',1,'2026-09-09','Sample resource (fictional)','2026-09-26T23:20:34.411Z','2026-09-26T23:20:34.411Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('f4468467-07f9-4ece-8bf1-4c1046982aa3','Family Health Clinic (OBOT)','mat_obot',NULL,'555-0208',NULL,NULL,'https://example.org/family-health-clinic-obot-','520 Sample Ave','Springfield','00000','Mon–Sat 8–8',NULL,'Office-based buprenorphine; telehealth follow-ups.','English, Spanish, Vietnamese',1,1,'buprenorphine',NULL,NULL,'Primary care clinic that prescribes buprenorphine as part of regular medical care, so clients can get their MAT, blood pressure and prenatal care in one place. Telehealth follow-ups after the first visit.','mat_buprenorphine,medical_care,telehealth,medication_management,spanish_speaking','1.0','adults,pregnant_parenting,families','Call for a same-week new-patient visit; bring a medication list. A navigator can attend the first visit.','Medicaid, Medicare and commercial plans; sliding scale for uninsured.',1,'2026-08-31','Sample resource (fictional)','2026-09-26T23:20:34.417Z','2026-09-26T23:20:34.417Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('32b80314-6f57-44c3-8d09-97a6a361014b','Recovery Rides','transportation',NULL,'555-0209',NULL,NULL,'https://example.org/recovery-rides','560 Sample Ave','Springfield','00000','Book 24h ahead',NULL,'Free rides to treatment and court.','English',0,1,NULL,NULL,NULL,'Volunteer drivers give free rides to treatment appointments, court dates, dosing and recovery meetings within the county.','transportation',NULL,'adults','Book by phone or online at least 24 hours ahead; same-day rides when a driver is free.','Free.',1,'2026-08-31','Sample resource (fictional)','2026-09-26T23:20:34.428Z','2026-09-26T23:20:34.428Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('17d18507-2e30-4820-b562-922b73cb947c','Northside IOP','intensive_outpatient',NULL,'555-0210',NULL,NULL,'https://example.org/northside-iop','600 Sample Ave','Springfield','00000','Evenings Mon/Wed/Thu',NULL,'Intensive outpatient; evening groups for working adults.','English',1,0,NULL,NULL,NULL,'Nine hours a week of evening group therapy plus a weekly individual session, designed for people who work or care for children during the day. Eight to twelve weeks, followed by an aftercare group.','intensive_outpatient,group_counseling,individual_counseling,aftercare,family_program','2.1','adults,men,women','Phone screening, then an assessment within a week. Referrals from residential programs are prioritised.','Medicaid and commercial insurance.',1,'2026-09-04','Sample resource (fictional)','2026-09-26T23:20:34.433Z','2026-09-26T23:20:34.433Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('abeee23a-3d22-4a92-9526-05b19c02a445','County Crisis Line','crisis_line',NULL,'988',NULL,NULL,'https://example.org/county-crisis-line','640 Sample Ave','Springfield','00000','24/7',NULL,'Mobile crisis team dispatch.','English, Spanish',1,1,NULL,NULL,NULL,'Call or text 988 any time. Counselors can dispatch the mobile crisis team, which comes to the person instead of sending police, and can arrange a same-day crisis bed.','crisis_24_7,mental_health,co_occurring,spanish_speaking',NULL,'adults,adolescents','Call or text 988.','Free.',1,'2026-09-09','Sample resource (fictional)','2026-09-26T23:20:34.448Z','2026-09-26T23:20:34.448Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('f95bce96-dee0-47c0-a09e-2378a6930513','Hands & Hearts Food Pantry','food',NULL,'555-0212',NULL,NULL,'https://example.org/hands-hearts-food-pantry','680 Sample Ave','Springfield','00000','Sat 9–12',NULL,'Groceries and hot meals; no ID required.','English',0,1,NULL,NULL,NULL,'Weekly groceries, hot meals on Saturdays and hygiene supplies. No ID or paperwork.','walk_in',NULL,'adults,families,unhoused','Walk in Saturday mornings.','Free.',1,'2026-09-13','Sample resource (fictional)','2026-09-26T23:20:34.448Z','2026-09-26T23:20:34.448Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('cf6f1659-1d8a-4e45-baa6-16ab4d2ff841','WorkFirst Employment Services','employment',NULL,'555-0213',NULL,NULL,'https://example.org/workfirst-employment-services','720 Sample Ave','Springfield','00000','Mon–Fri 9–5',NULL,'Job readiness, résumé help, fair-chance employers.','English, Spanish',0,1,NULL,NULL,NULL,'Job-readiness classes, résumé and interview help and a network of fair-chance employers who hire people with records. Paid work-experience placements for people in recovery.','employment,peer_support,spanish_speaking',NULL,'adults,justice_involved','Orientation every Monday at 9am; no referral needed.','Free.',1,'2026-08-08','Sample resource (fictional)','2026-09-26T23:20:34.454Z','2026-09-26T23:20:34.454Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('fcba5d14-c312-4c05-83f1-a8d803b2bce8','Recovery Café','recovery_community',NULL,'555-0214',NULL,NULL,'https://example.org/recovery-caf-','760 Sample Ave','Springfield','00000','Daily 10–6',NULL,'Peer-led recovery community; meetings and meals.','English',0,1,NULL,NULL,NULL,'A membership-based recovery community: meals, meetings, art and music groups, and peer recovery coaches. Members commit to 24 hours of sobriety before each visit and to a weekly recovery circle.','peer_support,walk_in,aftercare,employment',NULL,'adults,lgbtq,unhoused','Drop in for a tour any day; membership starts after a short orientation.','Free; members volunteer a few hours a month.',1,'2026-09-20','Sample resource (fictional)','2026-09-26T23:20:34.459Z','2026-09-26T23:20:34.459Z');
CREATE TABLE resource_photos (
  id TEXT PRIMARY KEY,
  resource_id TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE,
  caption TEXT,
  content_type TEXT NOT NULL,
  bytes INTEGER NOT NULL DEFAULT 0,
  width INTEGER, height INTEGER,
  -- Nullable: an attachment row reaches a device before its bytes do. Attachments are fetched by id once
  -- the rows have landed, because inlining every photo made a sync payload the phone could not parse.
  data_b64 TEXT,                       -- downscaled picture (JPEG/PNG/WebP), base64
  thumb_b64 TEXT,                       -- small JPEG thumbnail for lists, base64
  sort_order INTEGER NOT NULL DEFAULT 0,
  uploaded_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE policy_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('policy','procedure','contract')),
  description TEXT,
  effective_date TEXT,
  expires_at TEXT,
  filename TEXT,
  content_type TEXT,
  bytes INTEGER NOT NULL DEFAULT 0,
  file_b64 TEXT,
  search_text TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  uploaded_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE referrals (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  resource_id TEXT NOT NULL REFERENCES resources(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  referred_at TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  urgency TEXT DEFAULT 'routine',
  appointment_at TEXT,
  admitted_at TEXT,
  closed_at TEXT,
  outcome_enc TEXT,                    -- free text about a named person's treatment: encrypted
  barrier_enc TEXT,
  warm_handoff INTEGER DEFAULT 0,
  consent_id TEXT REFERENCES consents(id) ON DELETE SET NULL,
  -- set when the consent this referral relied on is revoked, so the worker is told to stop sharing
  consent_revoked INTEGER NOT NULL DEFAULT 0,
  follow_up_due TEXT,
  outcome_recorded_at TEXT,
  episode_id TEXT REFERENCES episodes(id) ON DELETE SET NULL,
  notes_enc TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
